contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will call getTokens with an amount of Ether 'payAmt'.
    // The rule: if the call succeeds, the caller's balance (as seen via c.balanceOf)
    // increases by the 'toGive' value that was distributed (which equals c.value before the call,
    // possibly capped to totalRemaining), and afterwards the caller becomes blacklisted.
    // If the caller was already blacklisted, the call must revert. Also, the contract's
    // ether balance increases by exactly payAmt when the call is made (no internal withdraw in same tx).

    function run(uint256 payAmt) public payable {
        require(address(this).balance >= payAmt);

        // read pre-state
        uint256 beforeContractEth = address(c).balance;
        uint256 beforeValue = c.value();
        uint256 beforeTotalRemaining = c.totalRemaining();
        bool beforeBlacklisted = c.blacklist(address(this));
        uint256 beforeBalance = c.balanceOf(address(this));

        // compute expected toGive according to contract logic (value capped by totalRemaining)
        uint256 expectedToGive = beforeValue;
        if (expectedToGive > beforeTotalRemaining) {
            expectedToGive = beforeTotalRemaining;
        }

        // perform the call and capture whether it reverted
        bool reverted = false;
        // must send Ether via low-level call to preserve reversion capture and forward value
        // but we need to invoke getTokens(), which is public; call on c with ABI encoding
        bytes memory payload = abi.encodeWithSignature("getTokens()");
        (bool ok,) = address(c).call{value: payAmt}(payload);
        if (!ok) { reverted = true; }

        // read post-state
        uint256 afterContractEth = address(c).balance;
        uint256 afterBalance = c.balanceOf(address(this));
        bool afterBlacklisted = c.blacklist(address(this));

        // General rule asserted below:
        // - If caller was already blacklisted before the call, the call must revert and nothing changed.
        // - Otherwise, if the call did not revert, then caller's token balance increased exactly by expectedToGive
        //   and caller is blacklisted after the call.
        // - In all cases, the contract's ether balance increases by exactly payAmt iff the call did not revert,
        //   otherwise it remains unchanged.
        assert(
            (
                // case: already blacklisted before -> must revert and no state change
                (beforeBlacklisted == true && reverted == true && afterBalance == beforeBalance && afterContractEth == beforeContractEth && afterBlacklisted == true)
            ) || (
                // case: not blacklisted before -> must not revert, balance increases by expectedToGive, becomes blacklisted, contract eth increased by payAmt
                (beforeBlacklisted == false && reverted == false && afterBalance == beforeBalance + expectedToGive && afterBlacklisted == true && afterContractEth == beforeContractEth + payAmt)
            )
        );
    }

    // Allow receiving Ether so the test harness can fund this contract.
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We call getTokens on c and assert the general invariant described above.
    function run(uint256 payAmt) public payable {
        // ensure this test contract can send the requested ether
        require(address(this).balance >= payAmt);

        // observe pre-call public values
        uint256 beforeContractEth = address(c).balance;
        uint256 beforeValue = c.value();
        uint256 beforeTotalRemaining = c.totalRemaining();
        bool beforeBlacklisted = c.blacklist(address(this));
        uint256 beforeBalance = c.balanceOf(address(this));

        // compute expected distributed amount according to contract logic
        uint256 expectedToGive = beforeValue;
        if (expectedToGive > beforeTotalRemaining) {
            expectedToGive = beforeTotalRemaining;
        }

        // perform the state-changing call as a top-level statement and catch revert
        bool reverted = false;
        try c.getTokens{value: payAmt}() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // observe post-call public values
        uint256 afterContractEth = address(c).balance;
        uint256 afterBalance = c.balanceOf(address(this));
        bool afterBlacklisted = c.blacklist(address(this));

        // Assert the general rule:
        // - If caller was already blacklisted before the call, the call must revert and no changes occur.
        // - Otherwise the call must not revert, caller balance increases by expectedToGive, caller becomes blacklisted,
        //   and contract's ether balance increases by exactly payAmt.
        assert(
            (
                beforeBlacklisted == true
                && reverted == true
                && afterBalance == beforeBalance
                && afterContractEth == beforeContractEth
                && afterBlacklisted == true
            ) || (
                beforeBlacklisted == false
                && reverted == false
                && afterBalance == beforeBalance + expectedToGive
                && afterBlacklisted == true
                && afterContractEth == beforeContractEth + payAmt
            )
        );
    }

    // Allow this contract to receive Ether so it can fund calls.
    receive() external payable { }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address ownerAddr, address spender, uint256 initial, uint256 newValue) public payable {
        require(ownerAddr == address(this)); // msg.sender for c calls will be this contract
        // set up: ensure allowance is initial by calling approve from this contract
        // first, if initial != 0 and current allowed is nonzero, the contract's approve will fail per implementation
        bool ok1 = c.approve(spender, initial);
        // record allowance after initial set
        uint256 allowedAfterInitial = c.allowance(address(this), spender);

        // Now attempt to set a different value newValue
        bool ok2 = c.approve(spender, newValue);
        uint256 allowedAfterNew = c.allowance(address(this), spender);

        // Rule: If the previous allowance (allowedAfterInitial) was nonzero and newValue is nonzero,
        // then approve must have returned false (ok2 == false) and allowance must be unchanged.
        // Otherwise no constraint (allow any behavior). Expressed as implication.
        assert(!(allowedAfterInitial != 0 && newValue != 0) || (ok2 == false && allowedAfterNew == allowedAfterInitial));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amt) public payable {
        require(to != address(0));
        // read balances before
        uint256 balFromBefore = c.balanceOf(address(this));
        uint256 balToBefore = c.balanceOf(to);

        bool reverted;
        // only attempt transfer if precondition holds: amount <= balance
        if (amt <= balFromBefore) {
            try c.transfer(to, amt) {
                reverted = false;
            } catch {
                reverted = true;
            }
        } else {
            // if not enough balance, we won't call transfer; mark as reverted=true to reflect no state change
            reverted = true;
        }

        uint256 balFromAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // General invariant: if transfer was attempted and succeeded (reverted==false), the sum of the two balances is unchanged
        // If transfer was not attempted or reverted, we cannot assume change, so require sum unchanged as well
        assert(balFromBefore + balToBefore == balFromAfter + balToAfter);
    }
    receive() external payable {}
}

