contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address to, uint256 amt) public payable {
        require(to != address(0));
        // require sender has at least amt to make a successful transfer meaningful
        uint256 balSenderBefore = c.balanceOf(address(this));
        require(balSenderBefore >= amt);

        uint256 balToBefore = c.balanceOf(to);

        bool reverted;
        try c.transfer(to, amt) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint256 balSenderAfter = c.balanceOf(address(this));
        uint256 balToAfter = c.balanceOf(to);

        // If transfer succeeded then sender decreased by amt and recipient increased by amt.
        // If it reverted then balances must be unchanged.
        assert(reverted ? (balSenderAfter == balSenderBefore && balToAfter == balToBefore)
                        : (balSenderAfter + amt == balSenderBefore && balToAfter == balToBefore + amt));
    }
    receive() external payable {}
}

